 33	async function stream(res: Response, s: Session, work: (emit: Emit) => Promise<void>) {
 34	  if (s.busy) {
 35	    res.status(409).json({ error: 'The agent is still answering the previous message.' });
 36	    return;
 37	  }
 38	  s.busy = true;
 39	  res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', Connection: 'keep-alive' });
 40	  const emit: Emit = (event) => res.write(`event: ${event.type}\ndata: ${JSON.stringify(event)}\n\n`);
 41	  try {
 42	    await work(emit);
 43	  } catch (err) {
 44	    console.error(err);
 45	    emit({ type: 'error', message: describe(err) });
 46	    emit({ type: 'done', stopReason: 'error' });
 47	  } finally {
 48	    s.busy = false;
 49	    res.end();
 50	  }
 51	}
